def is_woodall(n: int) -> bool:
    """
    Return True if n is a Woodall number, i.e. if there exists an integer k >= 1
    such that k * 2**k - 1 == n. Otherwise return False.

    Raises:
        TypeError: If n is not an integer.
    """
    if not isinstance(n, int):
        raise TypeError("Input must be an integer")

    if n < 1:
        return False

    k = 1
    while True:
        value = k * (1 << k) - 1  # 2**k is computed as 1 << k for speed
        if value == n:
            return True
        if value > n:
            return False
        k += 1

