import heapq
from collections import Counter
from typing import Dict

def rearange_string(S: str) -> str:
    """Write a function to check if the letters of a given string can be rearranged so that two characters that are adjacent to each other are different."""
    if not isinstance(S, str):
        raise ValueError("Input must be a string.")
    if S and (not S.islower() or not S.isalpha()):
        raise ValueError("String must contain only lowercase letters.")

    if not S:
        return ""

    freq: Dict[str, int] = Counter(S)
    n = len(S)

    if len(freq) == 1:
        return ""

    max_allowed = (n + 1) // 2
    if max(freq.values()) > max_allowed:
        return ""

    heap = [(-cnt, ch) for ch, cnt in freq.items()]
    heapq.heapify(heap)

    result = []
    prev_cnt, prev_ch = 0, ""

    while heap:
        cnt, ch = heapq.heappop(heap)
        result.append(ch)

        if prev_cnt < 0:
            heapq.heappush(heap, (prev_cnt, prev_ch))

        prev_cnt, prev_ch = cnt + 1, ch

    return "".join(result)

